import unicodedata
FIX={"o-jesulein-su":"o-jesulein-suss"}
def slug(t):
    t = unicodedata.normalize("NFKD",t).encode("ascii","ignore").decode().lower().replace("'", "").replace("’","")
    t = re.sub(r"[^a-z0-9]+","-",t).strip("-")
    return FIX.get(t,t)
existing = {p.name for p in (ROOT/"songs").iterdir()}
out=[]; ids=set()
for (t,c,cat,n,h,r,v) in R:
    i = slug(re.sub(r"\s*\(.*?\)\s*"," ",t)) if len(t)>40 or t.startswith(("At the","All People","Yankee","Ein","O Jesu")) else slug(t)
    assert i not in existing, i; assert i not in ids, i; ids.add(i)
    tags = {"hymn":["hymn"],"carol":["carol","christmas"],"folk":["folk"],"nursery":["nursery","children"],"seasonal":["seasonal"],"classical":["classical"]}[cat]+["beginner"]
    out.append(dict(id=i,title=t,composer=c,category=cat,tags=tags,difficulty=2,
        copyrightNotes=n,tuneHint=h,expectedRange=r,verifyPdFirst=bool(v),status="queued"))
json.dump(out, open(ROOT/"build/pd_interval_queue.json","w"), indent=1, ensure_ascii=False)
print(len(out), sum(o["verifyPdFirst"] for o in out))
for o in out: print(o["id"])
